import{_ as n,o as e,c as t,a3 as i}from"./chunks/framework.BvvarXmc.js";const m=JSON.parse('{"title":"Rekap Pendapatan & Laporan Kantin","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-kantin/rekap-penjualan.md","filePath":"panduan-kantin/rekap-penjualan.md","lastUpdated":null}'),r={name:"panduan-kantin/rekap-penjualan.md"};function l(s,a,p,u,o,k){return e(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="rekap-pendapatan-laporan-kantin" tabindex="-1">Rekap Pendapatan &amp; Laporan Kantin <a class="header-anchor" href="#rekap-pendapatan-laporan-kantin" aria-label="Permalink to &quot;Rekap Pendapatan &amp; Laporan Kantin&quot;">​</a></h1><p>Pengelola kantin dan bendahara sekolah dapat memantau akumulasi omset harian, barang terlaris, dan performa keuangan stan kantin secara berkala.</p><hr><h2 id="_1-memantau-omset-melalui-dashboard-kantin" tabindex="-1">1. Memantau Omset melalui Dashboard Kantin <a class="header-anchor" href="#_1-memantau-omset-melalui-dashboard-kantin" aria-label="Permalink to &quot;1. Memantau Omset melalui Dashboard Kantin&quot;">​</a></h2><p>Melalui halaman <strong>Dashboard Kantin</strong> (<code>/manage/canteen/dashboard</code>):</p><ul><li><strong>Total Pesanan Hari Ini</strong>: Jumlah transaksi kasir yang berhasil diproses.</li><li><strong>Pendapatan Hari Ini</strong>: Total uang masuk (kombinasi dompet digital dan tunai).</li><li><strong>Item Terjual Hari Ini</strong>: Jumlah porsi makanan dan minuman yang laku.</li><li><strong>Peringatan Stok Rendah (<em>Low Stock Alerts</em>)</strong>: Menampilkan daftar barang yang stoknya menipis agar pengelola segera melakukan pengadaan bahan.</li><li><strong>Grafik Penjualan 7 Hari Terakhir</strong>: Tren omset mingguan untuk menganalisis hari-hari tersibuk di kantin.</li></ul><hr><h2 id="_2-tutup-kas-bagi-hasil-supplier-mitra" tabindex="-1">2. Tutup Kas &amp; Bagi Hasil Supplier Mitra <a class="header-anchor" href="#_2-tutup-kas-bagi-hasil-supplier-mitra" aria-label="Permalink to &quot;2. Tutup Kas &amp; Bagi Hasil Supplier Mitra&quot;">​</a></h2><p>Untuk melakukan pencairan dana bagi pedagang titip jual dan rekonsiliasi kas resmi:</p><ul><li>Silakan buka panduan lengkap di <strong><a href="/panduan-kantin/tutup-buku">Tutup Buku &amp; Settlement Supplier</a></strong>.</li><li>Setiap tutup buku menghasilkan slip rincian omset kotor, komisi sekolah, dan hak bersih supplier yang siap dicairkan.</li></ul>',10)])])}const h=n(r,[["render",l]]);export{m as __pageData,h as default};
